mapper.select:
select cha.user_code as userCode from yh_user_sport_ch_record re
join yh_user_sport_challenge cha on re.ch_id = cha.ch_id
where re.ch_id = #{chId} and re.upload_tome = #{currentTime}

mapper.insert:
insert into yh_user_sport_ch_record (id, ch_id, upload_tome, 
  step, whether, reach
  )
values (#{id,jdbcType=INTEGER}, #{chId,jdbcType=INTEGER}, #{uploadTome,jdbcType=DATE}, 
  #{step,jdbcType=VARCHAR}, #{whether,jdbcType=VARCHAR}, #{reach,jdbcType=VARCHAR}
  )
